import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"兌","description":"高岛易断 - 兌","frontmatter":{"title":"兌","description":"高岛易断 - 兌"},"headers":[],"relativePath":"zh/classics/takashima/058.md","filePath":"zh/classics/takashima/058.md"}'),i={name:"zh/classics/takashima/058.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="兌" tabindex="-1">兌 <a class="header-anchor" href="#兌" aria-label="Permalink to “兌”">​</a></h1><h2 id="兌-1" tabindex="-1">兌 <a class="header-anchor" href="#兌-1" aria-label="Permalink to “兌”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>兑：亨，利贞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《兑》本《乾》体，《坤》三动来入《乾》，成《兑》，《兑》之“亨，利贞”，即《乾》之德也。《乾》之四德配四时，《兑》主秋，在夏冬之间，得兼三德，独不及元，故曰“兑亨，利贞”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>丽泽，兑，君子以朋友讲习。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>“丽”者，连也，“丽泽”，谓两泽相丽，是互相滋益也。朋友者，以互相讲习为益，故象朋友；《兑》为口，故象讲习。《论语》首章，以“学而时习’为悦，以有朋远来为乐，是悦乐之要，莫大于“朋友讲习”，此君子所以取其象于《兑》也。四爻曰“商兑”，商者，相与讲论之义，其象亦取之丽泽。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：运途平平，能得众心，自然获吉，惟逢三六之年，不利。</p><p>○　问营商：得人扶助，可以获利。</p><p>○　问功名：赖朋友之力可成。</p><p>○　问战征：屯兵陂泽之地，宜于两后营相约进攻，可以获胜。</p><p>○　问婚姻：必是朋友旧好。</p><p>○　问家宅：宅临泽水，宜与朋友同居。</p><p>○　问疾病：宜延相熟医师并诊，方可全愈。</p><p>○　问讼事：宜请朋友公评，不必涉讼。</p><p>○　问六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初居卦首，体得《乾》刚，“和兑”者，即和悦也。《乾》曰利物和义，是和即《彖》之所谓利也。人当初交，便觉和衷相济，以斯而悦，悦得其正矣，故吉。《传》曰“行未疑也”，谓人私曲疑虑，每生于转念，当其初，一片天心，固未尝间以人欲也。“和兑”在初，顺天而行，疑于何有？故不曰无疑，而曰“未疑”。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：运当初爻，以和为贵，万事获吉。</p><p>○　问战征：师克在和，民兵咸悦，有不战来归之象。</p><p>○　问营商：《兑》为正秋，万实告成，天地自然之美利也。营商得此，吉无不利。</p><p>○　问功名：得祥和之气，吉。</p><p>○　问婚姻：有家室和平之乐。</p><p>○　问家宅：一门和气，吉。</p><p>○　问行人：行当即归，无疑。</p><p>○　问讼事：即可和解。</p><p>○　问六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某来，请占谋事成否？筮得《兑》之《困》。</p><p>断曰：此卦一阴在二阳之上，以柔之卑，居刚之上。初爻得阳刚，刚以严，柔以和，以刚制柔，所谓和而不流者也。今足下占谋事得此爻，爻属于初，知其事尚在初起。“和”者，为彼此同心，和衷共济。初与四应，四曰“商兑”，“商”谓商量也，正合谋事之意。初爻《传》曰“行未疑”；谓其事必成无疑也；四爻《传》曰“有庆”，谓其事成后，又有庆福也。足下安心从事可也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二居下卦之中，以阳居阴，即《彖》所谓“刚中”也。二与五应，“孚兑”者，二孚于五，五亦孚于二，两相孚，即两相悦。二为臣，五为君，是君臣一心，相孚而相悦也，故吉。夫上下之心不相孚，则上下必不相悦，是以有悔，既得其孚，悔自亡矣。《象传》以“信志”释之，谓孚即信也，以其志之可信，故得吉也。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：运得中正，众心交孚，是以有吉，无悔。</p><p>○　问战征：上下一心，令出惟行，有匹夫不可夺之志，战无不克，吉。</p><p>○　问营商：贸易虽在逐利，要必以信为本，有信则彼此无欺，而商业乃可通行矣。</p><p>○　问婚姻：二五相孚，是阴阳相偶也，吉。</p><p>○　问家宅：“有孚挛如，富以其邻”，谓能与邻家，并力致富也。</p><p>○　问功名：《中孚》二爻曰，“我有好爵，吾与尔靡之”，有父子同升之吉。</p><p>○　问疾病：是因疑致疾，今既得相孚，灾悔自亡。</p><p>○　问六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某来，请占气运，筮得《兑》之《随》。</p><p>断曰：九二爻得刚中，刚中而孚，孚非阿好；既得相孚，无不相悦，是以吉而悔亡也。人生气运，亦贵得其刚中耳，刚则任事有肝胆，中则任事无私曲，志气刚强，运途中正，自然事事获吉。今足下占得此爻，知足下目下气运旺相。论《兑》为金运，以金水两运为佳；《兑》为秋，岁时以属秋令为佳。《大象》取“朋友讲习”，足下当择朋友，远小人，近君子，自得相扶为益，悔去而吉来也。</p><p>明治二十八年，占我国与美国交际，筮得《兑》之《随》。</p><p>断曰：孚者，信也，《中孚》《彖传》曰“悦而巽，孚乃化邦”，是知邦交之道，最宜信义相孚，使两无诈虞，化干戈为玉帛，实两邦之幸福也。今占我国与美国交际，得此爻辞，可知我国与美，两国交际，此后最为亲密，谓之“孚兑，吉，悔亡”。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三为《兑》主，即《彖》所谓“柔外”也。以柔招悦，故谓之“来”。初曰“和”，二曰“孚”，是不期悦而自悦，有相悦于无言耳。若专以阴柔悦人，亦以阴柔而致人悦，则所以来悦者，皆不以其道，则上下相蒙，适以长诈伪之风也，故“凶”。《传》以“不当位”释之，谓一阴居二阳之上，其位不当，欲以柔道致悦，其悦也，皆由强致而来，是失刚中之德矣。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：人品卑鄙，专以谄笑求悦，未免为人所贱矣。</p><p>○　问营商：通商之来，固宜和悦相招，然悦不以道，尔诈我虞，是失商道之正也。</p><p>○　问功名：奔竞而来，虽荣必败。</p><p>○　问战征：要皆招徕乌合之众也，不能久持。</p><p>○　问婚姻：有始合终离之象。</p><p>○　问疾病：病有外祟，其象本凶，三至四隔一爻，早则一日，迟则一月，可望愈快。</p><p>○　问讼事：是外来之祸，凶。</p><p>○　问六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>明治二十四年，有友某来，代占某氏气运，筮得《兑》之《夬》。</p><p>断曰：兑者，悦也，其悦宜就心中而出，不贵外袭而来。中出者，诚也，外来者，伪也。三曰“来兑”，是专以饰外为悦者也。今君代友占气运，得《兑》三爻，三以阴居阳，为《兑》之主，位本不当，其象专属阴柔，好以巧言悦人，知此友心地不正，颇有口密腹剑之象，未免凶矣。《大象》曰“朋友讲习”，君既谊属朋友，当随时劝诫，务令去伪存诚，乃得化凶为吉。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“介”，谓节操坚固之义，同《豫》之六二“介于石”之介；又两间曰介，四爻在三五之间，上承五之刚中，下比三之阴柔，是以一身介君子小人之间者也。“商”，商量也，《兑》为口，有商之象。四与初同体，初为事始，无所疑虑，故不待商；四则处上下之交，用刚用柔，皆须商榷，故曰“商兑”。商之而意难遽定，则中心游移，故曰“未宁”。因忧成病，故曰“介疾”。然未宁者终必宁，介然而疾，亦介然而喜矣。《兑》通《艮》，《艮》上《兑》下为《损》，《损》四曰“损其疾，使遄有喜”，其旨相同。《象传》以“有庆”释之，谓商而后宁，疾而有喜，则刚柔得中，天人相合，喜在一人，庆在天下矣。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：运途未稳，逆则有忧，顺则有喜，万事宜斟酌行之。</p><p>○　问营商：“四多惧”，营商在外，必有忧惧不安之事，商量出之，方得有喜。</p><p>○　问功名：功名必从艰苦患难而来者，方得大就。</p><p>○　问婚姻：一时疑惧未成，必待媒妁再三说合，终得成合有喜。</p><p>○　问家宅：现下宅中不安，致多疾厄。《兑》为秋，必待秋时，得以平安有喜。</p><p>○　问疾病：病由心神不安所致，得逢喜事，胸怀宽悦自愈。</p><p>○　问六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>某氏来，请占某缙神之气运，筮得《兑》之《节》。</p><p>断曰：兑者，悦也，“未宁”者，不悦也，兑而曰“商”，是介在悦不悦之中。“未宁”若有疾，得宁则有喜，赖此一商之功耳。四处内外之间，又当刚柔之交，孰轻孰重，皆须商酌，故曰“商兑未宁，介疾有喜”。今占气运，得《兑》四爻，知人生气运，亦无中立，从正则吉，从邪则凶，在人自取择耳。择而未安，譬若疾之在身，不能无忧，择之既定，自觉病去身安，喜从中来。四近君位，有贵人之象，能以商度事宜，上辅君德，下协民心，何庆如之？此功此德，正赖某缙绅也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五处外卦之中，秉《乾》之刚，即《彖传》所谓“刚中”也，悦以“利贞”，五得其贞焉。《兑》为秋，《剥》九月之卦，当《兑》之未孚而至《剥》，是孚之极也。其不言《兑》者，至五《兑》悦既深，浑若相忘，故不见为《兑》，而只见为《剥》。《剥》者即劳与难之事也，劳之难之，事虽为民，而王者则视之若剥也；忘劳忘死，王者虽以为剥，而民实不知其为剥也，故曰“孚于剥”。至此而民已视危为安，王者犹以安为危，故曰“有厉”。事本无厉，有者在君之心，亦凛凛乎其有也。五居尊位，固当然也。《传》释以“位正当”，谓居此位者，皆当存此心也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：位得其正，运当其盛，盛极则剥，尤当预防，能时时防剥，斯时时得盛矣。</p><p>○　问战征：“孚于剥”者，谓当生死存亡之地，军兵一心，感激奋勇，而不以为剥，诚可谓众志成城，无往不克矣。</p><p>○　问营商：剥者，剥削也，虽有剥削，而深信无疑，必有大利。</p><p>○　问功名：能安命，虽剥必亨。</p><p>○　问疾病：有剥肤之疾，速治则愈。</p><p>○　问六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十二年，友人某来，请占气运，筮得《兑》之《归妹》。</p><p>断曰：运当九五，阳刚中正，本届盛运，爻曰“孚于剥”，言其相悦无言，虽剥亦孚。安不忘危，有思患预防之象，亦有持盈保泰之道，《彖传》所谓“悦以利贞”，惟五当之。今君占气运，得《兑》五爻，知君目下气运得当，刚中柔外，众心咸孚，虽有剥削，亦得相悦以解，事事安和，得行其志。但在君心中，若以为剥，若以为厉，则剥无不复，厉无不安也。五与二正应，五虽不言吉，二之吉，即五之吉也。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上六辰在巳，得《巽》气，《巽》为绳，有引之象；《兑》又旁通《艮》，《艮》为手，是以能引，故曰“引兑”。六与三同体，三失位，六引之使应己，是因其来而引之；来既不正，引亦不当，而悦更失其道矣。爻虽未判吉凶，要之后事之失，亦所难免，故《传》以“未光”释之。《乾》为光，六变《乾》为《坤》，故曰“未光”。凡《易》称“引”者，多在阴爻，《萃》六二曰“引吉”，自五引二，引而升也，引在于上，故吉；此爻曰“引兑”，以六引三，引其来也，引在于后，故“未光”。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：上为卦之终，行运已极，必藉人引掖而能行，无吉无凶，平平而已。</p><p>○　问功名：虽得他人荐引，亦已晚矣。</p><p>○　问营商：得人引导，方可交易，上在卦外，是出洋经营也。“未光”者，未能大得利也。</p><p>○　问战征：《兑》属正西，“引兑”者，相引而入西也。是引兵向西，与三合队，但当上爻，时会已迟，恐未必能奏功也。</p><p>○　问疾病：内邪能引而外达，乃得望愈。</p><p>○　问家宅：宅地纯阴，与三合体，防有内外牵引之患。</p><p>○　问婚姻：爻象皆柔，恐是勾引而成，非夫妇之正礼也。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十二年，占某贵显气运，筮得《兑》之《履》。</p><p>断曰：上爻处外卦之极，无可复进，凡物极则变，有反而思退之象焉。今某贵显占得此爻，知贵显久居高位，意将引身退隐，以自娱乐，谓之“引兑”。是年冬，某贵显辞职归隐。</p>',104)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
